window.V5_CANVAS_CACHE = {};

window.getV5Canvas = function(key) {
  if (window.V5_CANVAS_CACHE[key]) return window.V5_CANVAS_CACHE[key];
  const entry = window.V5_RAW_RGBA[key];
  if (!entry) return null;
  const bin = atob(entry.b64);
  const bytes = new Uint8ClampedArray(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  const c = document.createElement('canvas');
  c.width = entry.w;
  c.height = entry.h;
  const ctx = c.getContext('2d');
  const imgData = new ImageData(bytes, entry.w, entry.h);
  ctx.putImageData(imgData, 0, 0);
  window.V5_CANVAS_CACHE[key] = c;
  return c;
};
